import sympy
from sympy import Matrix, eye, zeros, Expr

# Top-level setup: named object bindings
I2 = eye(2)
I3 = eye(3)
O2 = zeros(2, 2)
O3 = zeros(3, 3)

def conditions(witness) -> list[bool]:
    h1 = False
    h2 = False
    neg_q = False
    
    try:
        # If the witness is a matrix, it implicitly defines an element x in the 
        # finite-dimensional matrix algebra A = M_n(k) over the field k generated by its entries.
        if isinstance(witness, sympy.MatrixBase):
            h1 = True
            h2 = bool(witness.is_square and witness.shape[0] > 0)
            # In M_n(k), an element is a zero divisor iff it is singular.
            # Thus, it is NOT a zero divisor iff its determinant is non-zero (i.e., it is a unit).
            neg_q = bool(witness.det() != 0)
            
        # If the witness is a scalar, it implicitly defines an element in the 
        # 1-dimensional algebra A = k over the field k.
        elif isinstance(witness, (int, float, Expr)):
            h1 = True
            h2 = True
            # In a field, the only zero divisor is 0 (if we consider 0 a zero divisor).
            # Non-zero elements are units, hence not zero divisors.
            neg_q = bool(witness != 0)
    except Exception:
        pass

    return [h1, h2, neg_q]

CONDITION_LABELS = [
    "H_1: k is a field",
    "H_2: A is a finite-dimensional algebra over k",
    "¬Q: x is neither a left zero divisor nor a right zero divisor in A"
]

N_HYP = 2
NEG_Q_INDEX = 2